CREATE TABLE IF NOT EXISTS users (id INTEGER AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(20), avatar_url VARCHAR(500), role ENUM('admin','donatur') DEFAULT 'donatur', is_verified TINYINT(1) DEFAULT false, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, icon VARCHAR(50), created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (id INTEGER AUTO_INCREMENT PRIMARY KEY, user_id INTEGER NOT NULL, category_id INTEGER NOT NULL, title VARCHAR(255) NOT NULL, short_description VARCHAR(500), description TEXT, target_amount BIGINT NOT NULL, current_amount BIGINT DEFAULT 0, banner_image VARCHAR(500), status ENUM('active','completed','cancelled') DEFAULT 'active', deadline DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS campaign_images (id INTEGER AUTO_INCREMENT PRIMARY KEY, campaign_id INTEGER NOT NULL, image_url VARCHAR(500) NOT NULL, is_primary TINYINT(1) DEFAULT false, created_at DATETIME NOT NULL, FOREIGN KEY (campaign_id) REFERENCES campaigns(id));
CREATE TABLE IF NOT EXISTS squads (id INTEGER AUTO_INCREMENT PRIMARY KEY, campaign_id INTEGER NOT NULL, creator_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, target_amount BIGINT NOT NULL DEFAULT 0, current_amount BIGINT DEFAULT 0, invite_code VARCHAR(20) NOT NULL UNIQUE, status ENUM('active','completed','expired') DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (campaign_id) REFERENCES campaigns(id), FOREIGN KEY (creator_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS donations (id INTEGER AUTO_INCREMENT PRIMARY KEY, user_id INTEGER NOT NULL, campaign_id INTEGER NOT NULL, squad_id INTEGER, amount BIGINT NOT NULL, message TEXT, is_anonymous TINYINT(1) DEFAULT false, status ENUM('pending','success','failed','refunded') DEFAULT 'pending', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (campaign_id) REFERENCES campaigns(id), FOREIGN KEY (squad_id) REFERENCES squads(id));
CREATE TABLE IF NOT EXISTS transactions (id INTEGER AUTO_INCREMENT PRIMARY KEY, donation_id INTEGER NOT NULL UNIQUE, order_id VARCHAR(100) NOT NULL UNIQUE, payment_gateway VARCHAR(50) DEFAULT 'tripay', payment_method ENUM('qris','bank_transfer') NOT NULL, bank_code VARCHAR(20), qris_url VARCHAR(500), va_number VARCHAR(50), gross_amount BIGINT NOT NULL, fee_amount BIGINT DEFAULT 0, net_amount BIGINT DEFAULT 0, status ENUM('pending','settlement','expire','cancel','deny') DEFAULT 'pending', gateway_reference_id VARCHAR(100), gateway_response_raw TEXT, paid_at DATETIME, expired_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (donation_id) REFERENCES donations(id));
CREATE TABLE IF NOT EXISTS withdrawals (id INTEGER AUTO_INCREMENT PRIMARY KEY, campaign_id INTEGER NOT NULL, admin_id INTEGER NOT NULL, amount BIGINT NOT NULL, bank_name VARCHAR(50) NOT NULL, account_number VARCHAR(50) NOT NULL, account_holder VARCHAR(100) NOT NULL, status ENUM('pending','approved','rejected','transferred') DEFAULT 'pending', notes TEXT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (campaign_id) REFERENCES campaigns(id), FOREIGN KEY (admin_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id INTEGER AUTO_INCREMENT PRIMARY KEY, user_id INTEGER NOT NULL, title VARCHAR(255) NOT NULL, message TEXT, type ENUM('donation','campaign','withdrawal','system') DEFAULT 'system', is_read TINYINT(1) DEFAULT false, created_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS squad_members (id INTEGER AUTO_INCREMENT PRIMARY KEY, squad_id INTEGER NOT NULL, user_id INTEGER NOT NULL, role ENUM('creator','member') DEFAULT 'member', joined_at DATETIME NOT NULL, UNIQUE KEY squad_user_unique (squad_id, user_id), FOREIGN KEY (squad_id) REFERENCES squads(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(50) PRIMARY KEY, value TEXT, type ENUM('boolean','string','number','json') DEFAULT 'string', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
